def max_fill_rect(grid,nonsolid,i,j,c):
    # largest all-(c or noise) rectangle containing (i,j); returns (area, solid_c_count) or None if no solid c
    H,W=len(grid),len(grid[0])
    best=None
    for r1 in range(i+1):
        for r2 in range(i,H):
            # find max col span around j where all rows r1..r2 ok
            # expand left/right while column fully ok for rows r1..r2
            if not all(grid[r1+u][j]==c or (r1+u,j) in nonsolid for u in range(r2-r1+1)):
                continue
            c1=j
            while c1-1>=0 and all(grid[a][c1-1]==c or (a,c1-1) in nonsolid for a in range(r1,r2+1)): c1-=1
            c2=j
            while c2+1<W and all(grid[a][c2+1]==c or (a,c2+1) in nonsolid for a in range(r1,r2+1)): c2+=1
            area=(r2-r1+1)*(c2-c1+1)
            sc=sum(1 for a in range(r1,r2+1) for b in range(c1,c2+1) if grid[a][b]==c)
            if sc>0:
                cand=(area,sc)
                if best is None or cand>best: best=cand
    return best

def clean_noise5(grid):
    H,W=len(grid),len(grid[0])
    solid=classify(grid)
    pts=[(i,j) for i in range(H) for j in range(W) if solid[i][j]]
    nonsolid={(i,j) for i in range(H) for j in range(W) if not solid[i][j]}
    counts={}
    for r in grid:
        for v in r: counts[v]=counts.get(v,0)+1
    out=[r[:] for r in grid]
    for i in range(H):
        for j in range(W):
            if solid[i][j]: continue
            cands=set()
            for a,b in pts: cands.add(grid[a][b])
            scores={}
            for c in cands:
                mf=max_fill_rect(grid,nonsolid,i,j,c)
                if mf: scores[c]=mf+(counts[c],)
            if scores:
                out[i][j]=max(scores,key=lambda c:scores[c])
            else:
                ds=[((a-i)**2+(b-j)**2, grid[a][b]) for a,b in pts]
                out[i][j]=min(ds)[1]
    return out
