def solid_rects_bboxes(grid,solid):
    # enumerate maximal all-solid rectangles per color via row-pair spans
    H,W=len(grid),len(grid[0])
    bboxes=[]  # (color, r1,r2,c1,c2, area)
    for r1 in range(H):
        for r2 in range(r1,H):
            c=0
            while c<W:
                col=grid[r1][c]
                if all(solid[a][c] and grid[a][c]==col for a in range(r1,r2+1)):
                    c2=c
                    while c2+1<W and all(solid[a][c2+1] and grid[a][c2+1]==col for a in range(r1,r2+1)): c2+=1
                    bboxes.append((col,r1,r2,c,c2,(r2-r1+1)*(c2-c1+1)))
                    c=c2+1
                else: c+=1
    return bboxes

