from collections import deque
def comp_bboxes(grid,solid):
    H,W=len(grid),len(grid[0])
    seen=[[False]*W for _ in range(H)]
    bboxes=[]
    for i in range(H):
        for j in range(W):
            if solid[i][j] and not seen[i][j]:
                c=grid[i][j]; q=deque([(i,j)]); seen[i][j]=True
                r1=r2=i; c1=c2=j
                while q:
                    a,b=q.popleft()
                    r1=min(r1,a); r2=max(r2,a); c1=min(c1,b); c2=max(c2,b)
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and solid[x][y] and grid[x][y]==c:
                            seen[x][y]=True; q.append((x,y))
                bboxes.append((c,r1,r2,c1,c2,(r2-r1+1)*(c2-c1+1)))
    return bboxes

