from collections import Counter

def color_counts(grid):
    """Count of each color in the grid."""
    return Counter(v for row in grid for v in row)

def noise_colors(grid, frac=15):
    """Colors whose count is below max_count/frac: the scattered noise colors."""
    cnt = color_counts(grid)
    mx = max(cnt.values())
    return {c for c, n in cnt.items() if n < mx / frac}

def _best_rect(grid, noise, i, j, c):
    """Best (squareness, solid, area) rectangle of color c / noise cells containing (i, j)."""
    H, W = len(grid), len(grid[0])
    best = (0, 0, 0)
    for r1 in range(0, i + 1):
        for r2 in range(i, H):
            for c1 in range(0, j + 1):
                for c2 in range(j, W):
                    cells = [grid[a][b] for a in range(r1, r2 + 1) for b in range(c1, c2 + 1)]
                    if all(v == c or v in noise for v in cells):
                        solid = sum(1 for v in cells if v == c)
                        h, w = r2 - r1 + 1, c2 - c1 + 1
                        best = max(best, (min(h, w) / max(h, w), solid, h * w))
    return best

def clean_noise(grid, frac=15):
    """Recolor every noise cell (rare color) to the solid block color it belongs to."""
    H, W = len(grid), len(grid[0])
    noise = noise_colors(grid, frac)
    if not noise:
        return [r[:] for r in grid]
    pts = [(i, j) for i in range(H) for j in range(W) if grid[i][j] not in noise]
    out = [r[:] for r in grid]
    for i in range(H):
        for j in range(W):
            if grid[i][j] in noise:
                ds = [((a - i) ** 2 + (b - j) ** 2, grid[a][b]) for a, b in pts]
                m = min(d for d, _ in ds)
                cand = {c for d, c in ds if d == m}
                out[i][j] = max(cand, key=lambda c: _best_rect(grid, noise, i, j, c))
    return out

def classify(grid):
    H,W=len(grid),len(grid[0])
    solid=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            c=grid[i][j]
            ok=False
            # 2x2
            for di in (-1,0):
                for dj in (-1,0):
                    a,b=i+di,j+dj
                    if 0<=a<H-0 and 0<=b<W and a+1<H and b+1<W:
                        if all(grid[a+x][b+y]==c for x in(0,1) for y in(0,1)): ok=True
            # runs
            n=1
            b=j-1
            while b>=0 and grid[i][b]==c: n+=1; b-=1
            b=j+1
            while b<W and grid[i][b]==c: n+=1; b+=1
            if n>=4: ok=True
            n=1; a=i-1
            while a>=0 and grid[a][j]==c: n+=1; a-=1
            a=i+1
            while a<H and grid[a][j]==c: n+=1; a+=1
            if n>=4: ok=True
            solid[i][j]=ok
    return solid

def clusters_ge3(grid):
    H,W=len(grid),len(grid[0])
    seen=[[False]*W for _ in range(H)]; prot=set()
    for i in range(H):
        for j in range(W):
            if seen[i][j]: continue
            c=grid[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[(i,j)]
            while q:
