    majority = Counter(v for r in grid for v in r).most_common(1)[0][0]
    solid = solid_mask(grid)
    prot = protected_clusters(grid)
    bboxes = solid_component_bboxes(grid, solid)
    noise = [(a, b) for a in range(H) for b in range(W)
             if not solid[a][b] and (a, b) not in prot and grid[a][b] != majority]
    def trios(cur, i, j):
        s = set()
        for di in (0, -1):
            for dj in (0, -1):
                a, b = i + di, j + dj
                if 0 <= a < H - 1 and 0 <= b < W - 1:
                    vals = [cur[a + x][b + y] for x in (0, 1) for y in (0, 1) if (a + x, b + y) != (i, j)]
                    if len(set(vals)) == 1:
                        s.add(vals[0])
        return s
    for _ in range(maxit):
        nonsolid = set(noise)
        counts = Counter(v for r in cur for v in r)
        new = [r[:] for r in cur]; changed = False
        for i, j in noise:
            t = trios(cur, i, j)
            nb = Counter(); npos = []
            for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                x, y = i + da, j + db
                if 0 <= x < H and 0 <= y < W:
                    nb[cur[x][y]] += 1; npos.append((cur[x][y], x, y))
            if cur[i][j] in t or nb[cur[i][j]] >= 2:
                continue
            comps = {c for c in t if c != majority}
            nbc = {c for c, n in nb.items() if n >= 2}
            nbc2 = set()
            for c in nbc:
                ps = [(x, y) for (cc, x, y) in npos if cc == c]
                if any(abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1 for x1, y1 in ps for x2, y2 in ps if (x1, y1) != (x2, y2)):
                    nbc2.add(c)
            cands = comps if comps else (nbc2 if nbc2 else None)
            if cands is None:
                v = majority
            elif len(cands) == 1:
                v = next(iter(cands))
            else:
                ins = [c for c in cands if any(r1 <= i <= r2 and c1 <= j <= c2 for (cc, r1, r2, c1, c2, ar) in bboxes if cc == c)]
                c2_ = ins or list(cands)
                v = max(c2_, key=lambda c: (max_fill_rect(cur, nonsolid, i, j, c) or (0,)) + (counts[c],))
            if v != cur[i][j]:
                new[i][j] = v; changed = True
        cur = new
        if not changed:
            break
    return cur
'''
